PRAGMA user_version = 32;
CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE chats (key TEXT PRIMARY KEY, body TEXT NOT NULL, activity REAL NOT NULL DEFAULT 0);
CREATE TABLE messages (key TEXT PRIMARY KEY, chat_key TEXT NOT NULL REFERENCES chats(key), message_id INTEGER NOT NULL, date REAL NOT NULL, revision INTEGER NOT NULL, deleted INTEGER NOT NULL, body TEXT NOT NULL);
CREATE INDEX conversation_order ON messages(chat_key, message_id);
CREATE TABLE cursors (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE drafts (chat_key TEXT PRIMARY KEY REFERENCES chats(key), body TEXT NOT NULL);
CREATE TABLE blocks (id TEXT PRIMARY KEY, chat_key TEXT NOT NULL REFERENCES chats(key), revision TEXT NOT NULL, sources TEXT NOT NULL, rendered TEXT, state TEXT NOT NULL, error TEXT, date REAL NOT NULL, unanalysed TEXT, stage TEXT, guidance INTEGER, source_revisions TEXT);
CREATE TABLE jobs (id TEXT PRIMARY KEY, scope TEXT NOT NULL, role TEXT NOT NULL, input_revision TEXT NOT NULL, state TEXT NOT NULL, due REAL NOT NULL, payload TEXT NOT NULL, error TEXT);
CREATE INDEX due_work ON jobs(state,due);
CREATE TABLE incoming_deferred (scope TEXT PRIMARY KEY REFERENCES blocks(id) ON DELETE CASCADE, input_revision TEXT NOT NULL, due REAL NOT NULL, payload TEXT NOT NULL);
CREATE TABLE group_state (chat_key TEXT PRIMARY KEY REFERENCES chats(key), body TEXT NOT NULL);
CREATE TABLE group_intake (chat_key TEXT PRIMARY KEY REFERENCES chats(key), body TEXT NOT NULL);
CREATE TABLE group_sources (source TEXT PRIMARY KEY REFERENCES messages(key) ON DELETE CASCADE, chat_key TEXT NOT NULL, epoch INTEGER NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE group_briefing_days (chat_key TEXT NOT NULL REFERENCES chats(key),day TEXT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(chat_key,day));
CREATE TABLE group_briefing_runs (chat_key TEXT PRIMARY KEY REFERENCES chats(key),body TEXT NOT NULL);
CREATE TABLE group_briefing_batches (id TEXT PRIMARY KEY,chat_key TEXT NOT NULL REFERENCES chats(key),body TEXT NOT NULL);
CREATE TABLE group_briefing_attempts (id TEXT PRIMARY KEY,chat_key TEXT NOT NULL REFERENCES chats(key),day TEXT NOT NULL,state TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE group_briefing_chunks (id TEXT PRIMARY KEY,chat_key TEXT NOT NULL REFERENCES chats(key),day TEXT NOT NULL,fingerprint TEXT NOT NULL,valid INTEGER NOT NULL,body TEXT NOT NULL);
CREATE TABLE group_briefing_results (id TEXT PRIMARY KEY,chat_key TEXT NOT NULL REFERENCES chats(key),day TEXT NOT NULL,valid INTEGER NOT NULL,body TEXT NOT NULL);
CREATE TABLE group_briefing_dependencies (kind TEXT NOT NULL,owner_id TEXT NOT NULL,chat_key TEXT NOT NULL,source TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(kind,owner_id,source));
CREATE TABLE reservations (id TEXT PRIMARY KEY, bucket TEXT NOT NULL, engine TEXT NOT NULL, reserved INTEGER NOT NULL, actual INTEGER, status TEXT NOT NULL, created REAL NOT NULL, family TEXT NOT NULL DEFAULT 'daily');
CREATE TABLE receipts (id TEXT PRIMARY KEY, role TEXT NOT NULL, model TEXT NOT NULL, provider TEXT NOT NULL, usage TEXT NOT NULL, error TEXT, family TEXT NOT NULL DEFAULT 'daily');
CREATE TABLE budget_changes (at REAL NOT NULL,old INTEGER NOT NULL,new INTEGER NOT NULL,family TEXT NOT NULL DEFAULT 'daily');
CREATE TABLE derivatives (source TEXT PRIMARY KEY, revision INTEGER NOT NULL, body TEXT NOT NULL);
CREATE TABLE attachments (id TEXT PRIMARY KEY, chat_key TEXT NOT NULL REFERENCES chats(key), body TEXT NOT NULL);
CREATE TABLE selected_media (id TEXT PRIMARY KEY, chat_key TEXT NOT NULL REFERENCES chats(key), body TEXT NOT NULL);
CREATE TABLE operations (id TEXT PRIMARY KEY, chat_key TEXT NOT NULL REFERENCES chats(key), state TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE deletion_operations (id TEXT PRIMARY KEY, chat_key TEXT NOT NULL REFERENCES chats(key), state TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE avatars (peer TEXT PRIMARY KEY, photo_id TEXT NOT NULL, mime TEXT, expires REAL NOT NULL);
CREATE TABLE media_files (key TEXT PRIMARY KEY, revision INTEGER NOT NULL, variant TEXT NOT NULL, size INTEGER NOT NULL, mime TEXT, date REAL NOT NULL, used REAL NOT NULL);
CREATE TABLE media_catalogs (scope TEXT PRIMARY KEY, body TEXT NOT NULL, revision TEXT NOT NULL, updated REAL, stale INTEGER NOT NULL DEFAULT 1, error TEXT);
